    const g = ctx.createLinearGradient(0, -h - 16, 0, 0);
    g.addColorStop(0, enr ? '#e0c8ff' : '#e0fcff');
    g.addColorStop(0.25, enr ? '#8a4ae0' : '#4ab8ff');
    g.addColorStop(1, enr ? '#2a0a5a' : '#0a4a9a');
