    ctx.moveTo(back, 2);
    for (let x = back; x <= wf - 30; x += 10) ctx.lineTo(x, -h * (0.5 + 0.5 * ((x - back) / 230)) + Math.sin(x * 0.08 + lt * 0.3) * 4);
