      eaterEll(0, by0, mr * 1.15, mr, '#2a0610', P.line);
      eaterEll(0, by0 + mr * 0.15, mr * 0.8, mr * 0.7, '#5a0e1e', null);
      ctx.save();
      ctx.globalAlpha *= 0.6 + 0.3 * Math.sin(t * 0.2);
